Result Pattern และ Discriminated Unions:
// Result type
type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E }

// Discriminated union for domain errors
type DomainError =
  | { kind: "not-found"; id: string }
  | { kind: "validation"; field: string; message: string }
  | { kind: "rate-limited"; retryAfter: number }

// Type guard
function isNotFound(err: DomainError): err is { kind: "not-found"; id: string } {
  return err.kind === "not-found"
}

// Safe function
function parseUser(json: string): Result<User, DomainError> {
  try {
    const parsed = JSON.parse(json)
    if (!parsed.name) {
      return { ok: false, error: { kind: "validation", field: "name", message: "Required" } }
    }
    return { ok: true, value: { id: parsed.id, name: parsed.name, email: parsed.email } }
  } catch {
    return { ok: false, error: { kind: "validation", field: "json", message: "Invalid JSON" } }
  }
}

// Usage
const result = parseUser('{"id": 1, "name": "Alice"}')

if (result.ok) {
  console.log(result.value.name)  // TypeScript knows value is User
} else {
  // Exhaustive check
  switch (result.error.kind) {
    case "not-found":
      console.log(`Missing: ${result.error.id}`)
      break
    case "validation":
      console.log(`${result.error.field}: ${result.error.message}`)
      break
    case "rate-limited":
      console.log(`Wait ${result.error.retryAfter}s`)
      break
  }
}

