// Typed labeled break
type SearchResult = { found: boolean; pos: [number, number] }; // creates reusable type alias
function findValue(matrix: number[][], target: number): SearchResult { // defines reusable function block
  outer: for (let i = 0; i < matrix.length; i++) {
    for (let j = 0; j < matrix[i].length; j++) { // iterates with counter variable
      if (matrix[i][j] === target) { // conditionally executes following block
        return { found: true, pos: [i, j] }; // returns value to calling code
      }
    }
  }
  return { found: false, pos: [-1, -1] }; // returns value to calling code
}

