const client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

// Basic completion
async function complete(prompt: string): Promise<string> {
  const response = await client.chat.completions.create({
    model: 'gpt-4o-mini',
    messages: [{ role: 'user', content: prompt }],
  });
  return response.choices[0]?.message?.content ?? '';
}

// Structured output with Zod
const SentimentSchema = z.object({
  sentiment: z.enum(['positive', 'negative', 'neutral']),
  confidence: z.number().min(0).max(1),
});
type Sentiment = z.infer<typeof SentimentSchema>;

async function analyzeSentiment(text: string): Promise<Sentiment> {
  const response = await client.beta.chat.completions.parse({
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: 'Analyze sentiment.' },
      { role: 'user', content: text },
    ],
    response_format: zodResponseFormat(SentimentSchema, 'sentiment'),
  });
  return response.choices[0]?.message?.parsed as Sentiment;
}

// Streaming
async function* streamCompletion(prompt: string): AsyncIterable<string> {
  const stream = await client.chat.completions.create({
    model: 'gpt-4o-mini',
    messages: [{ role: 'user', content: prompt }],
    stream: true,
  });
  for await (const chunk of stream) {
    yield chunk.choices[0]?.delta?.content ?? '';
  }
}

